<?php
declare(strict_types=1);

function nzcc_other_member(array $conv,string $uid): string {foreach((array)($conv['members']??[])as$m){$m=(string)$m;if($m!==''&&$m!==$uid)return$m;}return'';}
function nzcc_blocked(array $db,string $a,string $b): bool {foreach($db['blocks']??[]as$x)if(($x['status']??'active')==='active'&&((($x['blocker_id']??'')===$a&&($x['blocked_id']??'')===$b)||(($x['blocker_id']??'')===$b&&($x['blocked_id']??'')===$a)))return true;return false;}
function nzcc_i_blocked(array $db,string $a,string $b): bool {foreach($db['blocks']??[]as$x)if(($x['status']??'active')==='active'&&($x['blocker_id']??'')===$a&&($x['blocked_id']??'')===$b)return true;return false;}
function nzcc_handle_post(string $action): never {
    nzc_session_open();$db=nzc_db_read();$u=nzc_require_user($db);if(!nzc_csrf_valid())throw new RuntimeException('درخواست نامعتبر است.');$cid=trim((string)($_POST['conversation_id']??''));$conv=nzchat_conversation($db,$cid);if(!$conv||!nzchat_member($conv,(string)$u['id'])||(($conv['type']??'')==='support'||($conv['post_id']??'')===NZC_SUPPORT_POST))throw new RuntimeException('گفتگوی کاربری معتبر نیست.');$other=nzcc_other_member($conv,(string)$u['id']);if($other==='')throw new RuntimeException('کاربر مقابل پیدا نشد.');
    if($action==='block_chat_user'){
        nzc_db_write(function(&$db)use($u,$other,$cid){foreach($db['blocks']??[]as&$b)if(($b['blocker_id']??'')===$u['id']&&($b['blocked_id']??'')===$other){$b['status']='active';$b['updated_at']=nzc_now();return;}unset($b);$db['blocks'][]=['id'=>nzc_uid('blk'),'blocker_id'=>$u['id'],'blocked_id'=>$other,'conversation_id'=>$cid,'status'=>'active','created_at'=>nzc_now()];});nzc_audit($u,'block_user','user',$other,['conversation_id'=>$cid]);nzc_flash('این کاربر مسدود شد و دیگر امکان ارسال پیام در این گفتگو وجود ندارد.','ok');nzc_redirect('/nz?page=chat&cid='.rawurlencode($cid));
    }
    if($action==='unblock_chat_user'){
        nzc_db_write(function(&$db)use($u,$other){foreach($db['blocks']??[]as&$b)if(($b['blocker_id']??'')===$u['id']&&($b['blocked_id']??'')===$other){$b['status']='inactive';$b['updated_at']=nzc_now();}unset($b);});nzc_audit($u,'unblock_user','user',$other);nzc_flash('مسدودسازی این کاربر برداشته شد.');nzc_redirect('/nz?page=chat&cid='.rawurlencode($cid));
    }
    if($action==='report_chat'){
        $reason=mb_substr(trim((string)($_POST['reason']??'مزاحمت یا محتوای نامناسب')),0,300);nzc_db_write(function(&$db)use($u,$other,$cid,$reason,$conv){$recent=array_values(array_filter($db['messages']??[],fn($m)=>($m['conversation_id']??'')===$cid));$recent=array_slice($recent,-10);$excerpt=[];foreach($recent as$m)$excerpt[]=mb_substr((string)($m['text']??''),0,160);$db['reports'][]=['id'=>nzc_uid('r'),'post_id'=>(string)($conv['post_id']??''),'post_title'=>nzc_post_title($db,(string)($conv['post_id']??'')),'reporter_id'=>$u['id'],'reported_user_id'=>$other,'reason'=>'گزارش گفتگو: '.$reason,'details'=>mb_substr(implode(' | ',$excerpt),0,1500),'priority'=>'high','conversation_id'=>$cid,'status'=>'open','created_at'=>nzc_now()];nzc_support_message($db,(string)$u['id'],'گزارش گفتگوی شما ثبت شد و با اولویت بالا توسط مدیر بررسی می‌شود.');});nzc_audit($u,'report_chat','conversation',$cid,['reported_user_id'=>$other,'reason'=>$reason]);nzc_flash('گفتگو برای بررسی مدیر گزارش شد.','ok');nzc_redirect('/nz?page=chat&cid='.rawurlencode($cid));
    }
    throw new RuntimeException('عملیات گفتگو معتبر نیست.');
}
function nzcc_controls_html(array $db,array $u,array $conv): string {
    if(($conv['type']??'')==='support'||($conv['post_id']??'')===NZC_SUPPORT_POST)return'';$other=nzcc_other_member($conv,(string)$u['id']);if($other==='')return'';$blocked=nzcc_i_blocked($db,(string)$u['id'],$other);$csrf=nzc_e($_SESSION['csrf']??'');return'<details class="nzcc-box"><summary>امنیت گفتگو</summary><div class="nzcc-actions"><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="'.($blocked?'unblock_chat_user':'block_chat_user').'"><input type="hidden" name="conversation_id" value="'.nzc_e($conv['id']??'').'"><button class="btn '.($blocked?'ghost':'danger').'">'.($blocked?'رفع مسدودسازی':'مسدودکردن کاربر').'</button></form><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="report_chat"><input type="hidden" name="conversation_id" value="'.nzc_e($conv['id']??'').'"><input name="reason" maxlength="300" placeholder="دلیل گزارش" required><button class="btn danger">گزارش گفتگو</button></form></div></details>';
}
